const YAML = require('yaml');

const sample = `# コメント付き
name: サンプル 太郎
role: developer
teams: [alpha, beta]
status: active
accounts:
  github: sample-dev
`;

const parsed = YAML.parse(sample);
const roundTrip = YAML.stringify(parsed);

return [{ json: {
  ok: true,
  parsed,
  teamsIsArray: Array.isArray(parsed.teams),
  nested: parsed.accounts.github,
  roundTrip,
} }];
